(()=>{'use strict';if(window.__saeInsightReady)return;window.__saeInsightReady=true;const $=(s,r=document)=>r.querySelector(s),all=(s,r=document)=>Array.from(r.querySelectorAll(s));const safe=v=>{try{const u=new URL(v,location.origin);return/^https?:$/.test(u.protocol)?u.href:''}catch{return''}};const esc=v=>String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const plain=s=>new DOMParser().parseFromString(s||'','text/html').body.textContent.trim();const dateLabel=raw=>{const m=String(raw||'').match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return'';const d=new Date(Date.UTC(Number(m[1]),Number(m[2])-1,Number(m[3])));return isNaN(d)?'':d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'})};const excerpt=e=>{const doc=new DOMParser().parseFromString(e.content?.$t||e.summary?.$t||'','text/html');const p=[...doc.querySelectorAll('p')].find(p=>p.textContent.trim().length>50&&!/^(ilustrasi|foto|image courtesy|sumber)\s*[:：]/i.test(p.textContent.trim()));return(p?.textContent||doc.body.textContent||'').trim().replace(/^(?:ilustrasi|foto|image courtesy|sumber)\s*:[\s\S]*?\)\s*/i,'')};const cfg={};all('.theme-config').forEach(el=>el.textContent.split(/\r?\n/).forEach(line=>{const i=line.indexOf('=');if(i>0)cfg[line.slice(0,i).trim()]=line.slice(i+1).trim()}));const logo=$('.site-header .brand-logo');if(logo)all('[data-footer-brand]').forEach(a=>a.replaceChildren(logo.cloneNode(true)));const toggle=$('.menu-toggle'),nav=$('.site-nav');const menu=(open,restore=false)=>{if(!nav||!toggle)return;nav.classList.toggle('is-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Tutup menu':'Buka menu');if(restore)toggle.focus({preventScroll:true})};toggle?.addEventListener('click',()=>menu(toggle.getAttribute('aria-expanded')!=='true'));document.addEventListener('click',e=>{if(nav?.classList.contains('is-open')&&!e.target.closest('.site-nav,.menu-toggle'))menu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('is-open')){e.preventDefault();menu(false,true)}});nav?.addEventListener('click',e=>{if(e.target.closest('a'))menu(false)});nav?.addEventListener('keydown',e=>{if(e.key==='Tab'&&innerWidth<768&&nav.classList.contains('is-open')){const links=all('a,button',nav);if(!e.shiftKey&&e.target===links.at(-1)){e.preventDefault();toggle.focus()}}});toggle?.addEventListener('keydown',e=>{if(e.key==='Tab'&&toggle.getAttribute('aria-expanded')==='true'){e.preventDefault();const links=all('a,button',nav);(e.shiftKey?links.at(-1):links[0])?.focus()}});matchMedia('(min-width:768px)').addEventListener('change',e=>{if(e.matches)menu(false)});$('[data-dismiss-announcement]')?.addEventListener('click',e=>e.currentTarget.closest('.announcement').remove());all('.newsletter-form').forEach(form=>{form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const status=$('.form-status',form);const url=safe(cfg.newsletter_url||'');if(!url){status.textContent='Newsletter belum diaktifkan. Anda dapat mengikuti artikel melalui RSS.';let link=document.createElement('a');link.href='/feeds/posts/default';link.textContent=' Buka RSS';status.append(link);return}const u=new URL(url);u.searchParams.set(cfg.newsletter_field||'email',$('input[type=email]',form).value);location.href=u.href})});const SOCIAL_PATHS={"instagram":"M7.8,2H16.2C19.4,2 22,4.6 22,7.8V16.2A5.8,5.8 0 0,1 16.2,22H7.8C4.6,22 2,19.4 2,16.2V7.8A5.8,5.8 0 0,1 7.8,2M7.6,4A3.6,3.6 0 0,0 4,7.6V16.4C4,18.39 5.61,20 7.6,20H16.4A3.6,3.6 0 0,0 20,16.4V7.6C20,5.61 18.39,4 16.4,4H7.6M17.25,5.5A1.25,1.25 0 0,1 18.5,6.75A1.25,1.25 0 0,1 17.25,8A1.25,1.25 0 0,1 16,6.75A1.25,1.25 0 0,1 17.25,5.5M12,7A5,5 0 0,1 17,12A5,5 0 0,1 12,17A5,5 0 0,1 7,12A5,5 0 0,1 12,7M12,9A3,3 0 0,0 9,12A3,3 0 0,0 12,15A3,3 0 0,0 15,12A3,3 0 0,0 12,9Z","linkedin":"M19 3A2 2 0 0 1 21 5V19A2 2 0 0 1 19 21H5A2 2 0 0 1 3 19V5A2 2 0 0 1 5 3H19M18.5 18.5V13.2A3.26 3.26 0 0 0 15.24 9.94C14.39 9.94 13.4 10.46 12.92 11.24V10.13H10.13V18.5H12.92V13.57C12.92 12.8 13.54 12.17 14.31 12.17A1.4 1.4 0 0 1 15.71 13.57V18.5H18.5M6.88 8.56A1.68 1.68 0 0 0 8.56 6.88C8.56 5.95 7.81 5.19 6.88 5.19A1.69 1.69 0 0 0 5.19 6.88C5.19 7.81 5.95 8.56 6.88 8.56M8.27 18.5V10.13H5.5V18.5H8.27Z","twitter":"M22.46,6C21.69,6.35 20.86,6.58 20,6.69C20.88,6.16 21.56,5.32 21.88,4.31C21.05,4.81 20.13,5.16 19.16,5.36C18.37,4.5 17.26,4 16,4C13.65,4 11.73,5.92 11.73,8.29C11.73,8.63 11.77,8.96 11.84,9.27C8.28,9.09 5.11,7.38 3,4.79C2.63,5.42 2.42,6.16 2.42,6.94C2.42,8.43 3.17,9.75 4.33,10.5C3.62,10.5 2.96,10.3 2.38,10C2.38,10 2.38,10 2.38,10.03C2.38,12.11 3.86,13.85 5.82,14.24C5.46,14.34 5.08,14.39 4.69,14.39C4.42,14.39 4.15,14.36 3.89,14.31C4.43,16 6,17.26 7.89,17.29C6.43,18.45 4.58,19.13 2.56,19.13C2.22,19.13 1.88,19.11 1.54,19.07C3.44,20.29 5.7,21 8.12,21C16,21 20.33,14.46 20.33,8.79C20.33,8.6 20.33,8.42 20.32,8.23C21.16,7.63 21.88,6.87 22.46,6Z","facebook":"M12 2.04C6.5 2.04 2 6.53 2 12.06C2 17.06 5.66 21.21 10.44 21.96V14.96H7.9V12.06H10.44V9.85C10.44 7.34 11.93 5.96 14.22 5.96C15.31 5.96 16.45 6.15 16.45 6.15V8.62H15.19C13.95 8.62 13.56 9.39 13.56 10.18V12.06H16.34L15.89 14.96H13.56V21.96A10 10 0 0 0 22 12.06C22 6.53 17.5 2.04 12 2.04Z","youtube":"M10,15L15.19,12L10,9V15M21.56,7.17C21.69,7.64 21.78,8.27 21.84,9.07C21.91,9.87 21.94,10.56 21.94,11.16L22,12C22,14.19 21.84,15.8 21.56,16.83C21.31,17.73 20.73,18.31 19.83,18.56C19.36,18.69 18.5,18.78 17.18,18.84C15.88,18.91 14.69,18.94 13.59,18.94L12,19C7.81,19 5.2,18.84 4.17,18.56C3.27,18.31 2.69,17.73 2.44,16.83C2.31,16.36 2.22,15.73 2.16,14.93C2.09,14.13 2.06,13.44 2.06,12.84L2,12C2,9.81 2.16,8.2 2.44,7.17C2.69,6.27 3.27,5.69 4.17,5.44C4.64,5.31 5.5,5.22 6.82,5.16C8.12,5.09 9.31,5.06 10.41,5.06L12,5C16.19,5 18.8,5.16 19.83,5.44C20.73,5.69 21.31,6.27 21.56,7.17Z","whatsapp":"M12.04 2C6.58 2 2.13 6.45 2.13 11.91C2.13 13.66 2.59 15.36 3.45 16.86L2.05 22L7.3 20.62C8.75 21.41 10.38 21.83 12.04 21.83C17.5 21.83 21.95 17.38 21.95 11.92C21.95 9.27 20.92 6.78 19.05 4.91C17.18 3.03 14.69 2 12.04 2M12.05 3.67C14.25 3.67 16.31 4.53 17.87 6.09C19.42 7.65 20.28 9.72 20.28 11.92C20.28 16.46 16.58 20.15 12.04 20.15C10.56 20.15 9.11 19.76 7.85 19L7.55 18.83L4.43 19.65L5.26 16.61L5.06 16.29C4.24 15 3.8 13.47 3.8 11.91C3.81 7.37 7.5 3.67 12.05 3.67M8.53 7.33C8.37 7.33 8.1 7.39 7.87 7.64C7.65 7.89 7 8.5 7 9.71C7 10.93 7.89 12.1 8 12.27C8.14 12.44 9.76 14.94 12.25 16C12.84 16.27 13.3 16.42 13.66 16.53C14.25 16.72 14.79 16.69 15.22 16.63C15.7 16.56 16.68 16.03 16.89 15.45C17.1 14.87 17.1 14.38 17.04 14.27C16.97 14.17 16.81 14.11 16.56 14C16.31 13.86 15.09 13.26 14.87 13.18C14.64 13.1 14.5 13.06 14.31 13.3C14.15 13.55 13.67 14.11 13.53 14.27C13.38 14.44 13.24 14.46 13 14.34C12.74 14.21 11.94 13.95 11 13.11C10.26 12.45 9.77 11.64 9.62 11.39C9.5 11.15 9.61 11 9.73 10.89C9.84 10.78 10 10.6 10.1 10.45C10.23 10.31 10.27 10.2 10.35 10.04C10.43 9.87 10.39 9.73 10.33 9.61C10.27 9.5 9.77 8.26 9.56 7.77C9.36 7.29 9.16 7.35 9 7.34C8.86 7.34 8.7 7.33 8.53 7.33Z","arrow-left":"M20,11V13H8L13.5,18.5L12.08,19.92L4.16,12L12.08,4.08L13.5,5.5L8,11H20Z","arrow-right":"M4,11V13H16L10.5,18.5L11.92,19.92L19.84,12L11.92,4.08L10.5,5.5L16,11H4Z"};const resize=(s,w=800)=>{try{const u=new URL(s);if(u.hostname==='images.unsplash.com'){u.searchParams.set('auto','format');u.searchParams.set('fit','crop');u.searchParams.set('w',String(w));u.searchParams.set('q','75')}else if(/(^|\.)(blogger\.googleusercontent\.com|\d+\.bp\.blogspot\.com|lh\d+\.googleusercontent\.com)$/.test(u.hostname)){u.pathname=u.pathname.replace(/\/s\d+(-[^/]*)?\//,'/s'+w+'/').replace(/\/w\d+-h\d+(-[^/]*)?\//,'/w'+w+'/');if(u.pathname.includes('/blogger_img_proxy/'))u.pathname=u.pathname.replace(/=w\d+[^/]*$/,'=w'+w+'-h'+Math.round(w*2/3)+'-p-k-no-nu')}return u.href}catch{return''}};const image=e=>{let src=e.media$thumbnail?.url||'';if(!src)src=new DOMParser().parseFromString(e.content?.$t||'','text/html').querySelector('img')?.getAttribute('src')||'';return src?safe(src):''};const entryURL=e=>safe((e.link||[]).find(l=>l.rel==='alternate')?.href||'');const outline=(d)=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${d}"></path></svg>`;const commentIcon=outline('M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9H13a8.5 8.5 0 0 1 8 8v.5Z');const shareIcon=outline('M18 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM6 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Zm12 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6ZM8.6 10.5l6.8-4M8.6 13.5l6.8 4');const copyIcon=outline('M9 9h11v11H9zM5 15H3V3h12v2');const networks=[['whatsapp','WhatsApp'],['facebook','Facebook'],['x','X'],['telegram','Telegram'],['linkedin','LinkedIn']];const socialIcon=key=>key==='x'?outline('M4 3h4l12 18h-4L4 3ZM20 3 4 21'):key==='telegram'?outline('m22 3-7 18-4-8-9-4 20-6ZM11 13 22 3'):`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="currentColor"><path d="${SOCIAL_PATHS[key]||''}"></path></svg>`;const shareURL=(key,raw,title)=>{const url=encodeURIComponent(raw),text=encodeURIComponent(title);return key==='whatsapp'?'https://api.whatsapp.com/send?text='+text+'%20'+url:key==='facebook'?'https://www.facebook.com/sharer/sharer.php?u='+url:key==='x'?'https://x.com/intent/tweet?url='+url+'&text='+text:key==='telegram'?'https://t.me/share/url?url='+url+'&text='+text:'https://www.linkedin.com/sharing/share-offsite/?url='+url};function cardActions(url,title,count=0){const n=Math.max(0,Number(count)||0);return`<div class="card-actions"><a class="comment-link" href="${esc(url)}#comments" aria-label="Lihat ${n} komentar: ${esc(title)}">${commentIcon}<span>${n} komentar</span></a><details class="card-share"><summary aria-label="Bagikan artikel: ${esc(title)}">${shareIcon}<span>Bagikan</span></summary><div class="share-popover"><p>Bagikan artikel</p>${networks.map(([k,label])=>`<a href="${esc(shareURL(k,url,title))}"target="_blank"rel="noopener noreferrer">${socialIcon(k)}<span>${label}</span></a>`).join('')}<button type="button" data-copy-url="${esc(url)}">${copyIcon}<span>Salin tautan</span></button></div></details></div>`}
all('[data-card-actions]').forEach(host=>{const card=host.closest('.blog-card'),url=safe(card?.dataset.postUrl||'');if(url)host.outerHTML=cardActions(url,$('.card-title a',card)?.textContent||document.title,host.dataset.comments)});document.addEventListener('click',async e=>{all('.card-share[open]').forEach(d=>{if(!d.contains(e.target))d.open=false});const summary=e.target.closest('.card-share summary');if(summary)all('.card-share[open]').forEach(d=>{if(d!==summary.parentElement)d.open=false});const btn=e.target.closest('[data-copy-url]');if(!btn)return;const label=$('span',btn);try{await navigator.clipboard.writeText(btn.dataset.copyUrl);label.textContent='Tautan tersalin';setTimeout(()=>label.textContent='Salin tautan',2000)}catch{label.textContent='Buka artikel untuk menyalin'}});document.addEventListener('keydown',e=>{if(e.key==='Escape')all('.card-share[open]').forEach(d=>{d.open=false;$('summary',d)?.focus()})});function card(e,variant='normal'){const url=entryURL(e);if(!url)return null;const title=e.title?.$t||'Artikel',src=image(e),labels=(e.category||[]).slice(0,3),date=new Date(e.published?.$t),stamp=dateLabel(e.published?.$t),author=e.author?.[0]?.name?.$t||'';const el=document.createElement('article');el.className='blog-card';el.dataset.postUrl=url;const photo=`<a class="card-photo" href="${esc(url)}" tabindex="-1" aria-hidden="true">${src?`<img alt="${esc(title)}"src="${esc(resize(src,800))}"srcset="${[480,800,1200].map(w=>esc(resize(src,w))+' '+w+'w').join(',')}"sizes="(min-width:1280px) 384px, (min-width:768px) 45vw, 100vw"width="900"height="600"loading="lazy"decoding="async"/>`:''}</a>`;const heading=`<h2 class="card-title"><a href="${esc(url)}">${esc(title)}</a></h2><p class="card-excerpt">${esc(excerpt(e).slice(0,170))}</p>`;const meta=`<p class="card-meta">${esc(author)}${author&&stamp?' • ':''}${esc(stamp)}</p>`;if(variant==='related'){const avatar=safe(e.author?.[0]?.gd$image?.src||''),words=plain(e.content?.$t||'').split(/\s+/).length;el.innerHTML=photo+`<div class="card-copy"><div class="post-badge"><a href="/search/label/${encodeURIComponent(labels[0]?.term||'')}">${esc(labels[0]?.term||'Artikel')}</a><span>${Math.max(1,Math.ceil(words/220))} min read</span></div>`+heading+`<div class="related-author">${avatar?`<img src="${esc(avatar)}"width="40"height="40"alt=""loading="lazy"/>`:`<span class="author-initial"aria-hidden="true">${esc(author.slice(0,1).toUpperCase())}</span>`}<div><strong>${esc(author)}</strong><time>${esc(stamp)}</time></div></div></div>`}else el.innerHTML=photo+`<div class="card-copy">`+meta+heading+`<div class="tags">${labels.map(l=>`<a class="tag"href="/search/label/${encodeURIComponent(l.term)}">${esc(l.term)}</a>`).join('')}</div></div>`;$('.card-copy',el).insertAdjacentHTML('beforeend',cardActions(url,title,e.thr$total?.$t));all('img',el).forEach(img=>img.addEventListener('error',()=>{img.hidden=true},{once:true}));const tones=[['#f9f5ff','#6941c6','#e9d7fe'],['#f0f9ff','#026aa2','#b9e6fe'],['#fdf2fa','#c11574','#fcceee'],['#ecfdf3','#027a48','#abefc6'],['#eef4ff','#3538cd','#c7d7fe'],['#fffaeb','#b54708','#fedf89']];const named={news:0,bisnis:1,showbiz:2,bola:3,lifestyle:2,kesehatan:3,tekno:4,otomotif:5,regional:1};all('.tags .tag',el).forEach(a=>{const name=a.textContent.toLowerCase(),idx=named[name]??([...name].reduce((n,c)=>n+c.charCodeAt(0),0)%tones.length),t=tones[idx];a.style.setProperty('--tag-bg',t[0]);a.style.setProperty('--tag-color',t[1]);a.style.setProperty('--tag-border',t[2])});return el}
const cached=new Map(),feedTotals=new Map();async function fetchJSON(path){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),10000);try{const r=await fetch(path,{credentials:'omit',signal:ctl.signal});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(!d.feed)throw Error('Feed tidak valid');return d.feed}finally{clearTimeout(timer)}}
async function entries(label,count,start=1,needImages=true){const filter=label&&label!=='recent'?'/-/'+encodeURIComponent(label):'',tail=`${filter}?alt=json&orderby=published&max-results=${count}&start-index=${start}`,key=label+'|'+count+'|'+start+'|'+needImages;if(cached.has(key))return cached.get(key);const promise=(async()=>{const feed=await fetchJSON('/feeds/posts/summary'+tail);feedTotals.set(label,Number(feed.openSearch$totalResults?.$t)||0);let list=feed.entry||[];if(needImages&&list.some(e=>!image(e))){try{const full=await fetchJSON('/feeds/posts/default'+tail);const map=new Map((full.entry||[]).map(e=>[e.id?.$t,e]));list.forEach(e=>{const f=map.get(e.id?.$t);if(f)e.content=f.content})}catch{}}return list})();cached.set(key,promise);try{return await promise}catch(e){cached.delete(key);throw e}}
const[labelRaw,countRaw]=($('.feed-config')?.textContent.trim()||'recent|7').split('|');const mainLabel=labelRaw?.trim()||'recent',mainCount=Math.max(1,Math.min(30,Number(countRaw)||7));const currentPage=Math.max(1,Math.min(10000,Number(new URLSearchParams(location.search).get('page'))||1));function pagination(total){const nav=$('.home-page .pagination');if(!nav)return;const pages=Math.max(1,Math.ceil(total/mainCount)),page=Math.min(currentPage,pages),url=p=>p===1?'/':'/?page='+p;const svgLeft='<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M19 12H5m6-6-6 6 6 6"></path></svg>',svgRight='<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M5 12h14m-6-6 6 6-6 6"></path></svg>';const seq=pages<=7?Array.from({length:pages},(_,i)=>i+1):page<5?[1,2,3,4,5,'…',pages]:page>pages-4?[1,'…',pages-4,pages-3,pages-2,pages-1,pages]:[1,'…',page-1,page,page+1,'…',pages];const side=(p,disabled,content,aria)=>disabled?`<button class="btn" type="button" disabled aria-label="${aria}">${content}</button>`:`<a class="btn" href="${url(p)}" aria-label="${aria}">${content}</a>`;nav.innerHTML=side(page-1,page===1,svgLeft+'<span class="page-word">Previous</span>','Previous Page')+`<div class="page-numbers">${seq.map(n=>n==='…'?'<span class="page-ellipsis">…</span>':`<a href="${url(n)}"class="${n===page?'current':''}"${n===page?'aria-current="page"':''}>${n}</a>`).join('')}</div><span class="mobile-page-count">Page ${page} of ${pages}</span>`+side(page+1,page===pages,'<span class="page-word">Next</span>'+svgRight,'Next Page')}
function enhanceNative(host,list){const cards=all(':scope > .blog-card',host);if(cards.length!==list.length||!list.every((e,i)=>new URL(entryURL(e)).pathname===new URL(cards[i].dataset.postUrl,location.href).pathname))return false;cards.forEach((node,i)=>{const e=list[i],p=$('.card-excerpt',node),meta=$('.card-meta',node),author=e.author?.[0]?.name?.$t||'',stamp=dateLabel(e.published?.$t);if(p)p.textContent=excerpt(e).slice(0,170);if(meta)meta.textContent=author+(author&&stamp?' • ':'')+stamp;const action=$('.card-actions',node);if(action)action.outerHTML=cardActions(entryURL(e),e.title?.$t||'',e.thr$total?.$t)});host.dataset.hydrated='true';return true}
function loadFeed(host){const run=async()=>{const type=host.dataset.feed,count=type==='home'?mainCount:type==='related'?3:4,label=type==='home'?mainLabel:'recent',native=type==='home'&&currentPage===1&&all(':scope > .blog-card .card-photo img',host).length===count;host.setAttribute('aria-busy','true');try{let list=await entries(label,count,type==='home'?(currentPage-1)*mainCount+1:1,!native);if(type==='related')list=list.filter(e=>new URL(entryURL(e)).pathname!==location.pathname).slice(0,2);if(list.length){if(type==='home')pagination(feedTotals.get(label)||list.length);if(!native||!enhanceNative(host,list)){if(native&&list.some(e=>!image(e)))list=await entries(label,count,1,true);const nodes=list.map(e=>card(e,type==='related'?'related':'normal')).filter(Boolean);if(nodes.length)host.replaceChildren(...nodes)}}else if(!host.querySelector('.blog-card')){const msg=document.createElement('p');msg.className='feed-status';msg.textContent=label==='recent'?'Belum ada artikel yang diterbitkan.':'Belum ada artikel pada kategori ini.';host.replaceChildren(msg)}}catch{if(!host.querySelector('.blog-card')){const msg=document.createElement('div');msg.className='feed-status';msg.textContent='Artikel belum dapat dimuat. ';const retry=document.createElement('button');retry.className='btn small';retry.type='button';retry.textContent='Coba lagi';retry.addEventListener('click',run);msg.append(retry);const a=document.createElement('a');a.href='/search?max-results=7';a.textContent=' Buka arsip';msg.append(a);host.replaceChildren(msg)}}finally{host.setAttribute('aria-busy','false');host.dispatchEvent(new Event('feedready'))}};run()}
